fn solution() {
    let t: usize = {
        let mut buf = String::new();
        std::io::stdin().read_line(&mut buf).unwrap();
        buf.trim_end().parse().unwrap()
    };

    let mut ans = Vec::with_capacity(t);
    for _ in 0..t {
        let (a, b, x, y, n): (i64, i64, i64, i64, i64) = {
            let mut buf = String::new();
            std::io::stdin().read_line(&mut buf).unwrap();
            let mut iter = buf.split_whitespace();
            (
                iter.next().unwrap().parse().unwrap(),
                iter.next().unwrap().parse().unwrap(),
                iter.next().unwrap().parse().unwrap(),
                iter.next().unwrap().parse().unwrap(),
                iter.next().unwrap().parse().unwrap(),
            )
        };

        use std::cmp;
        let res1 = {
            let i = cmp::min(a - x, n);
            let j = cmp::min(b - y, n - i);
            (a - i) * (b - j)
        };
        let res2 = {
            let i = cmp::min(b - y, n);
            let j = cmp::min(a - x, n - i);
            (b - i) * (a - j)
        };
        ans.push(cmp::min(res1, res2));
