fn solution() -> Result<(), Box<dyn Error>> {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let t: i32 = lines.next().unwrap()?.parse()?;
    for _ in 0..t {
        let (_, mut k): (i32, i32) = {
            let line = lines.next().unwrap()?;
            let mut lines = line.split(" ").map(|s| s.parse());
            (lines.next().unwrap()?, lines.next().unwrap()?)
        };
        let mut a: Vec<(i32, usize)> = lines
            .next()
            .unwrap()?
            .split(" ")
            .map(|s| s.parse::<i32>().unwrap())
            .enumerate()
            .map(|s| (s.1, s.0))
            .collect();
        let b: HashMap<i32, usize> = a.clone().into_iter().collect();
        a.sort_by_key(|k| k.0);

        let mut row_prev: Option<usize> = None;
        for (v, i) in a {
            let j = b[&v];
            if let Some(rp) = &row_prev
                && rp + 1 != j {
                    row_prev = None;
                    k -= 1;
                }
            row_prev = Some(i);
        }

        if k > 0 {
            println!("Yes");
        } else {
            println!("No");
        }
    }
    Ok(())
}

