fn solution() {
    input! {
        N: usize,
        F: [ [usize; 10]; N],
        P: [ [i64; 11]; N],
    }

    let mut max = std::i64::MIN;
    for ind in 1..(1 << 10) {
        let mut c = vec![0_usize; N];
        let mut res = ind;
        let mut count = 0;
        while res > 0 {
            let is = res & 1;
            for i in 0..N {
                c[i] += F[i][count] * is;
            }
            res >>= 1;
            count += 1;
        }
        let mut sum = 0;
        for (ind, cc) in c.iter().enumerate() {
            sum += P[ind][*cc];
        }
        max = cmp::max(max, sum);
    }
    println!("{}", max);
}

