fn solution() {
    let mut input = String::new();
    use std::io::{self, prelude::*};
    io::stdin().read_to_string(&mut input).unwrap();

    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let m: usize = it.next().unwrap().parse().unwrap();

    let x: Vec<usize> = it
        .by_ref()
        .take(n + m)
        .map(|x| x.parse().unwrap())
        .collect();
    let t: Vec<bool> = it.take(n + m).map(|x| x == "1").collect();

    let residents: Vec<_> = x
        .into_iter()
        .zip(t)
        .map(|(xi, ti)| {
            let kind = if ti { Driver } else { Rider };
            Resident { kind, address: xi }
        })
        .collect();

    let mut left = Vec::with_capacity(n);
    let mut current = None;
    for resident in residents.iter() {
        match resident.kind {
            Driver => current = Some(current.map(|x| x + 1).unwrap_or(0)),
            Rider => left.push(current),
        }
    }

    let mut right = Vec::with_capacity(n);
    current = None;
    for resident in residents.iter().rev() {
        match resident.kind {
            Driver => current = Some(current.map(|x| x - 1).unwrap_or(m - 1)),
            Rider => right.push(current),
        }
    }
    right.reverse();

    let mut rider_addresses = Vec::with_capacity(n);
    let mut driver_addresses = Vec::with_capacity(m);

    for resident in residents {
        match resident.kind {
            Rider => rider_addresses.push(resident.address),
            Driver => driver_addresses.push(resident.address),
        }
    }

    let closest: Vec<_> = rider_addresses
        .into_iter()
        .zip(left.into_iter().zip(right))
        .map(|(address, (a, b))| match (a, b) {
            (Some(left), Some(right))
                if driver_addresses[right] - address < address - driver_addresses[left] =>
            {
                right
            }
            (Some(left), _) => left,
            (None, Some(right)) => right,
            _ => panic!("!"),
        })
        .collect();

    let answer = closest
        .into_iter()
        .fold(vec![0; m], |mut answer, driver_id| {
            answer[driver_id] += 1;
            answer
        });

    let stdout = io::stdout();
    let mut lock = stdout.lock();

    for a in answer {
        write!(&mut lock, "{} ", a).unwrap();
    }
}

