                if cycle[j] == now {
                    start = j;
                    break;
                }
            }
            break;
        }
    }

    let mut s1 = 0;
    let mut s2 = 0;
    let len = cycle.len() - start;
    for i in 0..start {
        s1 += cycle[i];
    }
    for i in start..cycle.len() {
        s2 += cycle[i];
    }

    let mut ans = s1 + (n - start) / len * s2;
    for _ in 0..(n - start) % len {
        ans += now;
        now = now * now % m;
    }
    println!("{}", ans);
