fn solution<T: Ord>(arr: &mut [T], ascending: bool) {
    if arr.len() <= 1 {
        return;
    }

    let comparator: fn(&T, &T) -> Ordering = if ascending {
        |a, b| a.cmp(b)
    } else {
        |a, b| b.cmp(a)
    };

    let mut i = (arr.len() - 1) / 2;
    loop {
        let mut root = i;

        loop {
            let mut idx = root;
            let l = 2 * root + 1;
            let r = 2 * root + 2;

            if l < arr.len() && comparator(&arr[l], &arr[idx]) == Ordering::Greater {
                idx = l;
            }

            if r < arr.len() && comparator(&arr[r], &arr[idx]) == Ordering::Greater {
                idx = r;
            }

            if idx == root {
                break;
            }

            arr.swap(root, idx);
            root = idx;
        }

        if i == 0 {
            break;
        }

        i -= 1;
    }

    let mut end = arr.len() - 1;

    while end > 0 {
        arr.swap(0, end);

        let mut root = 0;

        loop {
            let mut idx = root;
            let l = 2 * root + 1;
            let r = 2 * root + 2;

            if l < end && comparator(&arr[l], &arr[idx]) == Ordering::Greater {
                idx = l;
            }

            if r < end && comparator(&arr[r], &arr[idx]) == Ordering::Greater {
                idx = r;
            }

            if idx == root {
                break;
            }

            arr.swap(root, idx);
            root = idx;
        }

        end -= 1;
    }
}

