fn solution() {
    let stdin_handle = std::io::stdin();
    let stdin = stdin_handle.lock();
    let mut it = stdin.lines().skip(1);
    let (a, b) = (it.next().unwrap().unwrap(), it.next().unwrap().unwrap());
    let (ab, bb) = (a.as_bytes(), b.as_bytes());
    let mut mls = Vec::<u32>::with_capacity(b.len());
    let mut mrs = Vec::<u32>::with_capacity(b.len());
    for i in 0..a.len() {
        if mls.len() >= b.len() {
            break;
        }
        if bb[mls.len()] == ab[i] {
            mls.push(i as u32);
        }
    }
    for i in (0..a.len()).rev() {
        if mrs.len() >= b.len() {
            break;
        }
        if bb[b.len() - mrs.len() - 1] == ab[i] {
            mrs.push(i as u32);
        }
    }
    mrs.reverse();
    let mut ans = 1;
    for i in 0..b.len() - 1 {
        ans = std::cmp::max(ans, mrs[i + 1] - mls[i]);
    }
    println!("{}", ans);
}

