    }

    fn sort<T: Ord>(arr: &mut [T], mut lo: usize, mut hi: usize) {
        while lo < hi {
            let pivot = hi;
            let mut i = lo;
            let mut j = hi - 1;

            loop {
                while arr[i] < arr[pivot] {
                    i += 1;
                }

                while j > 0 && arr[j] > arr[pivot] {
                    j -= 1;
                }

                if j == 0 || i >= j {
                    break;
                } else if arr[i] == arr[j] {
                    i += 1;
                    j -= 1;
                } else {
                    arr.swap(i, j);
                }
            }

            arr.swap(i, pivot);
            let pivot_idx = i;

            if pivot_idx - lo < hi - pivot_idx {
                if pivot_idx > 0 {
                    sort(arr, lo, pivot_idx - 1);
                }
                lo = pivot_idx + 1;
            } else {
                sort(arr, pivot_idx + 1, hi);
                hi = pivot_idx.saturating_sub(1);
            }
        }
    }

    sort(arr, 0, arr.len() - 1);
}

