fn solution() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let S: Vec<usize> = buf.split_whitespace().map(|s| s.parse().unwrap()).collect();
    let N = S[0];

    let mut dp1 = vec![None; N + 1];
    let mut dp2 = vec![vec![None; N + 1]; N + 1];
    {
        let mut s = S[1..=2].to_vec();
        s.sort();
        let (a, b) = (s[0], s[1]);
        dp1[a].get_or_insert(0);
        dp1[b].get_or_insert(0);
        dp1[0].get_or_insert(0);
        dp2[a][b].get_or_insert(0);
    }

    let mut base = 0;
    let mut q = Vec::new();

    for i in 1..N {
        let mut s = S[3 * i..3 * (i + 1)].to_vec();
        s.sort();
        let (a, b, c) = (s[0], s[1], s[2]);

        if a == c {
            base += 1;
            continue;
        } else if a == b {
            for x in 1..=N {
                if x < a {
                    if let Some(v) = dp2[x][a] {
                        q.push((x, c, v + 1));
                    }
                } else if x < c {
                    if let Some(v) = dp2[a][x] {
                        q.push((x, c, v + 1));
                    }
                } else {
                    if let Some(v) = dp2[a][x] {
                        q.push((c, x, v + 1));
                    }
                }
            }
            if let Some(v) = dp2[c][c] {
                q.push((a, a, v + 1));
            }
        } else if b == c {
            for x in 1..=N {
                if x < a {
                    if let Some(v) = dp2[x][c] {
                        q.push((x, a, v + 1));
                    }
                } else if x < c {
                    if let Some(v) = dp2[x][c] {
                        q.push((a, x, v + 1));
                    }
                } else {
                    if let Some(v) = dp2[c][x] {
                        q.push((a, x, v + 1));
                    }
                }
            }
            if let Some(v) = dp2[a][a] {
                q.push((c, c, v + 1));
            }
        } else {
            if let Some(v) = dp2[a][a] {
                q.push((b, c, v + 1));
            }
            if let Some(v) = dp2[b][b] {
                q.push((a, c, v + 1));
            }
            if let Some(v) = dp2[c][c] {
                q.push((a, b, v + 1));
            }
        }

        q.push((a, b, dp1[0].unwrap()));
        q.push((a, c, dp1[0].unwrap()));
        q.push((b, c, dp1[0].unwrap()));

        for x in 1..=N {
            if let Some(v) = dp1[x] {
                for y in &[a, b, c] {
                    if x < *y {
                        q.push((x, *y, v));
                    } else {
                        q.push((*y, x, v));
                    }
                }
            }
        }

        while let Some((a, b, v)) = q.pop() {
            if dp2[a][b].is_none() || dp2[a][b].unwrap() < v {
                let u = dp2[a][b].get_or_insert(v);
                *u = v;
                for i in &[0, a, b] {
                    let u = dp1[*i].get_or_insert(v);
                    *u = max(*u, v);
                }
            }
        }
    }

    let s = S[S.len() - 1];
    println!(
        "{}",
        match dp2[s][s] {
            Some(_v) => base + max(1 + dp2[s][s].unwrap_or(0), dp1[0].unwrap_or(0)),
            None => base + dp1[0].unwrap(),
        }
    );
}

