fn solution() {
    let mut input_str = String::new();
    std::io::stdin().read_to_string(&mut input_str).unwrap();

    let input_parts = input_str.split_whitespace().collect::<Vec<_>>();
    let mut input_parts_it = input_parts.iter().cloned();
    let mut next = || input_parts_it.next().unwrap();

    let n: usize = next().parse().unwrap();

    struct Pr {
        and_mask: u16,
        bitmap: u16,
    }

    let prs = (0..n)
        .map(|_| {
            let a: usize = next().parse().unwrap();
            let mut and_mask: u16 = 0;
            let mut bitmap: u16 = 0;

            for _ in 0..a {
                let x: u32 = next().parse().unwrap();
                let y: u8 = next().parse().unwrap();
                and_mask |= 1u16 << x;
                if y != 0 {
                    bitmap |= 1u16 << x;
                }
            }

            Pr {
                and_mask: and_mask >> 1,
                bitmap: bitmap >> 1,
            }
        })
        .collect::<Vec<_>>();

    let best = (0..(1u16 << n))
        .filter(|&bitmap| {
            prs.iter().enumerate().all(|(i, pr)| {
                if (bitmap & (1 << i)) != 0 {
                    (bitmap & pr.and_mask) == pr.bitmap
                } else {
                    true
                }
            })
        })
        .map(|bitmap| bitmap.count_ones())
        .max()
        .unwrap();

    println!("{}", best);
}

