        let mut all_rows: Vec<&str> = (&mut lines).take(n).collect();
        let rows_1st: HashSet<&str> = all_rows
            .iter()
            .map(|s| s.split(" ").next().unwrap())
            .collect();

        let m_cols: Vec<&str> = (&mut lines).take(m).collect();
        let idx_col: Vec<&str> = m_cols
            .iter()
            .find(|s| rows_1st.contains(s.split(" ").next().unwrap()))
