void solution(int *arr, int size) {
  for (int i = 1; i < size; i++) {
    int key = arr[i];
    int low = 0;
    int high = i - 1;
    int index;

    while (low <= high) {
      int mid = low + ((high - low) / 2);

      if (arr[mid] == key) {
        index = mid + 1;
        break;
      }
      if (arr[mid] < key) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }

    if (low > high) {
      index = low;
    }

    int j = i - 1;
    while (j >= index) {
      arr[j + 1] = arr[j];
      j--;
    }

    arr[j + 1] = key;
  }
}

