fn solution<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();

    for i in 1..len {
        let key = arr[i].clone();

        let mut low = 0;
        let mut high = i;

        while low < high {
            let mid = low + (high - low) / 2;

            if arr[mid] < key {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        arr[low..=i].rotate_right(1);
        arr[low] = key;
    }
}

