    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut entries = buf.split_whitespace();
    let q: usize = entries.next().unwrap().parse().unwrap();
    for _ in 0..q {
        let n: usize = entries.next().unwrap().parse().unwrap();
        let mut sum = 0;
        let mut l: Vec<isize> = Vec::with_capacity(n);
        for _ in 0..n {
            let l_i: isize = entries.next().unwrap().parse().unwrap();
            let l_i = if l_i == 1 { 1 } else { -1 };
            sum += -l_i;
            l.push(l_i);
        }
        let mut l = l.into_iter().rev().collect::<Vec<_>>();
        let mut r: Vec<isize> = Vec::with_capacity(n);
        for _ in 0..n {
            let r_i: isize = entries.next().unwrap().parse().unwrap();
            let r_i = if r_i == 1 { 1 } else { -1 };
            sum += -r_i;
            r.push(r_i);
        }

        for i in 1..n {
            l[i] += l[i - 1];
            r[i] += r[i - 1];
        }

        if sum == 0 {
            println!("0");
            continue;
        }
        let mut l_ind = HashMap::new();
        for i in 0..n {
            l_ind.entry(l[i]).or_insert(i);
        }

        let mut min = if let Some(cost) = l_ind.get(&(-sum)) {
            *cost + 1
        } else {
            usize::max_value()
        };

        for i in 0..n {
            if r[i] == -sum {
                min = min.min(i + 1);
            }
            if let Some(cost) = l_ind.get(&(-(sum + r[i]))) {
                min = min.min(cost + 1 + i + 1)
            }
        }
        if min == usize::max_value() {
            min = 2 * n
        }
        println!("{}", min);
    }
}

