        let mut stack: Vec<usize> = vec![1];
        while let Some(edge_from) = stack.pop() {
            trail[edge_from] = true;
            for (edge_to, &is_exits_path) in graph[edge_from].iter().enumerate() {
                if is_exits_path && !trail[edge_to] && !stack.contains(&edge_to) {
                    stack.push(edge_to);
