fn solution() {
    let stdin = stdin();
    let stdout = stdout();

    let stdin = stdin.lock();
    let stdout = stdout.lock();
    let mut stdout = BufWriter::new(stdout);

    let mut stdin = stdin.lines();
    let mut read = || stdin.next().unwrap().unwrap();

    let nn: usize = read().parse().unwrap_or_default();
    for _i in 0..nn {
        let n: usize = read().parse().unwrap_or_default();
        let mut w: Box<[u32]> = read()
            .split_ascii_whitespace()
            .take(n)
            .map(|t| t.parse().unwrap_or_default())
            .collect();
        w.sort();

        let mut prev = None;
        let mut cnt = 0;
        let mut stat = Vec::new();
        for x in w.iter() {
            if prev == Some(x) {
                cnt += 1;
            } else {
                if let Some(_) = prev.replace(x) {
                    stat.push(cnt)
                }
                cnt = 1;
            }
        }
        if let Some(_) = prev {
            stat.push(cnt)
        }

        let mut stat_sums = vec![0_usize; stat.len()];
        let mut stat_sums_reverse = vec![0_usize; stat.len()];
        for i in 0..stat.len() {
            stat_sums[i] = stat[i] + if i > 0 { stat_sums[i - 1] } else { 0 };
        }

        for i in 0..stat.len() {
            stat_sums_reverse[i] =
                stat[stat.len() - (i + 1)] + if i > 0 { stat_sums_reverse[i - 1] } else { 0 };
        }

        let mut assign_lo = Vec::new();
        let mut assign_hi = Vec::new();
        let mut bucket = 1;
        while bucket <= n {
            let mut pos = stat_sums.partition_point(|&x| x <= bucket);
            let mut taken = if pos > 0 { stat_sums[pos - 1] } else { 0 };
            let mut added = bucket - taken;
            assign_lo.push((taken, added));

            pos = stat_sums_reverse.partition_point(|&x| x <= bucket);
            taken = if pos > 0 {
                stat_sums_reverse[pos - 1]
            } else {
                0
            };
            added = bucket - taken;
            assign_hi.push((taken, added));
            bucket *= 2;
        }

        let mut best = usize::MAX;
        for lo in &assign_lo {
            for hi in &assign_hi {
                let overflow;
                let mid_taken;
                if lo.0 + hi.0 > n {
                    overflow = lo.0 + hi.0 - n;
                    mid_taken = 0;
                } else {
                    overflow = 0;
                    mid_taken = n - lo.0 - hi.0;
                }

                let mid_added = if mid_taken > 0 {
                    mid_taken.next_power_of_two() - mid_taken
                } else {
                    1
                };

                let total_added = mid_added + lo.1 + hi.1 + overflow;

                best = min(total_added, best);
            }
        }

        writeln!(stdout, "{}", best).unwrap();
    }

    stdout.flush().unwrap();
}

