fn solution() {
    input! {
        n: usize,
        x: usize
    }

    let mut v: Vec<(usize, usize)> = vec![(1, 1)];
    for i in 0..n {
        let (iall, ipat) = v[i];
        let all = 3 + 2 * iall;
        let pat = 1 + 2 * ipat;
        v.push((all, pat));
    }
    let mut sum = 0;
    let mut queue: Vec<(usize, usize)> = vec![(n, x)];
    while let Some((level, eat)) = queue.pop() {
        if level == 0 && eat == 1 {
            sum += 1;
            continue;
        }
        if eat <= level {
            continue;
        }
        let (all, pat) = v[level];
        if eat == all {
            sum += pat;
            continue;
        }
        let mid = all / 2;
        match eat.cmp(&(mid + 1)) {
            std::cmp::Ordering::Less => {
                queue.push((level - 1, eat - 1));
            }
            std::cmp::Ordering::Equal => {
                let (_, pat) = v[level - 1];
                sum += pat + 1;
            }
            std::cmp::Ordering::Greater => {
                let (_, pat) = v[level - 1];
                sum += pat + 1;
                queue.push((level - 1, eat - mid - 1));
            }
        }
    }
    println!("{}", sum);
}

