    if (flag[i] != 0) {
      continue;
    }

    flag[i] = 1;
    if (adj[i] == NULL) {
      iso++;
      continue;
    }

    q[0] = i;
    for (head = 0, tail = 1, tmp = 0; head < tail; head++) {
      u = q[head];
      for (p = adj[u]; p != NULL; p = p->next) {
        w = p->v;
        if (flag[w] == 0) {
          flag[w] = -flag[u];
          q[tail++] = w;
        } else if (flag[w] == flag[u]) {
          tmp = 1;
        }
      }
    }
    if (tmp != 0) {
      nonbip++;
    } else {
      bip++;
    }
  }

  printf("%lld\n", ((long long)iso * (N * 2 - iso)) +
                       ((long long)(bip + nonbip) * (bip + nonbip)) +
                       ((long long)bip * bip));
  fflush(stdout);
  return 0;
}

