    let stdout = std::io::stdout();
    let mut reader = std::io::BufReader::new(stdin.lock());
    let mut writer = std::io::BufWriter::new(stdout.lock());

    let n: usize = {
        let mut buf = String::new();
        reader.read_line(&mut buf).unwrap();
        buf.trim_end().parse().unwrap()
    };
    let mut x: Vec<i64> = vec![0; n];
    let mut y: Vec<i64> = vec![0; n];
    let mut p: Vec<i64> = vec![0; n];
    for i in 0..n {
        let mut buf = String::new();
        reader.read_line(&mut buf).unwrap();
        let mut iter = buf.split_whitespace();
        x[i] = iter.next().unwrap().parse().unwrap();
        y[i] = iter.next().unwrap().parse().unwrap();
        p[i] = iter.next().unwrap().parse().unwrap();
    }

    let mut a: Vec<Vec<i64>> = vec![vec![std::i64::MAX; n]; 1 << n];
    let mut b: Vec<Vec<i64>> = vec![vec![std::i64::MAX; n]; 1 << n];
    for i in 0..(1 << n) {
        for j in 0..n {
            a[i][j] = cmp::min(a[i][j], x[j].abs());
            b[i][j] = cmp::min(b[i][j], y[j].abs());
            if i & 1 << j == 0 {
                continue;
            }
            for k in 0..n {
                a[i][k] = cmp::min(a[i][k], (x[j] - x[k]).abs());
                b[i][k] = cmp::min(b[i][k], (y[j] - y[k]).abs());
            }
        }
    }

    let pow = |mut a: usize, mut n: usize| {
        let mut res = 1;
        while n > 0 {
            if n & 1 > 0 {
                res *= a;
            }
            a *= a;
            n >>= 1;
        }
        res
    };

    let mut ans = vec![std::i64::MAX; n + 1];
    for i in 0..pow(3, n) {
        let mut c = 0;
        let mut x = i;
        let mut s = 0;
        let mut t = 0;
        for j in 0..n {
            let y = x % 3;
            if y == 1 {
                s += 1 << j;
                c += 1;
            } else if y == 2 {
                t += 1 << j;
                c += 1;
            }
            x /= 3;
        }

        let mut d = vec![std::i64::MAX; n];
        for i in 0..n {
            d[i] = cmp::min(a[s][i], b[t][i]);
        }
        let res = { d.iter().enumerate().fold(0, |acc, (i, k)| acc + p[i] * k) };
        ans[c] = cmp::min(ans[c], res);
    }

    for i in 0..=n {
        writeln!(writer, "{}", ans[i]).unwrap();
    }
}

