fn solution<T: Copy + Ord>(arr: &mut [T]) {
    if arr.len() <= 1 {
        return;
    }

    let len = arr.len();
    let mut sub_array_size = 1;

    while sub_array_size < len {
        let mut start_index = 0;

        while len - start_index > sub_array_size {
            let end_idx = if start_index + 2 * sub_array_size > len {
                len
            } else {
                start_index + 2 * sub_array_size
            };

            let mid = sub_array_size;

            let left_half = arr[start_index..start_index + mid].to_vec();
            let right_half = arr[start_index + mid..end_idx].to_vec();

            let mut l = 0;
            let mut r = 0;

            for v in &mut arr[start_index..end_idx] {
                if r == right_half.len() || (l < left_half.len() && left_half[l] < right_half[r]) {
                    *v = left_half[l];
                    l += 1;
                } else {
                    *v = right_half[r];
                    r += 1;
                }
            }

            start_index = end_idx;
        }

        sub_array_size *= 2;
    }
}

