        .next()
        .unwrap()
        .unwrap()
        .trim()
        .split(' ')
        .map(|n| n.parse().unwrap())
        .collect();

    let mut reach: Vec<HashSet<u32>> = vec![];
    reach.reserve(n as usize);
    for _ in cost.iter() {
        reach.push(HashSet::new());
    }

    let mut pairs: Vec<Vec<u32>> = vec![];
    for l in lines {
        let lv: Vec<u32> = l
            .unwrap()
            .trim()
            .split(' ')
            .map(|n| n.parse::<u32>().unwrap() - 1)
            .collect();

        reach[lv[0] as usize].insert(lv[1]);
        reach[lv[1] as usize].insert(lv[0]);
        pairs.push(lv);
