fn solution() -> io::Result<()> {
    let _input = String::new();

    let out = io::stdout();
    let mut out = BufWriter::new(out.lock());

    let mut write_and_flush = |line: &str| {
        writeln!(out, "{}", line).unwrap();
        out.flush().unwrap();
    };

    let is_finished = |line: &str| line.eq("0");

    let mut target = 3i64;

    loop {
        write_and_flush(&format!("? 1 {}", target));

        let mut buf = String::new();
        io::stdin().read_line(&mut buf)?;
        let line = buf.trim();

        if is_finished(line) {
            break;
        }

        let path1: i64 = line.parse().unwrap();
        if path1 == -1 {
            write_and_flush(&format!("! {}", target - 1));
            break;
        }

        write_and_flush(&format!("? {} 1", target));

        let mut buf = String::new();
        io::stdin().read_line(&mut buf)?;
        let line = buf.trim();

        if is_finished(line) {
            break;
        }

        let path2: i64 = line.parse().unwrap();

        if path1 != path2 {
            write_and_flush(&format!("! {}", path1 + path2));
            break;
        } else {
            target += 1;
        }
    }
    Ok(())
