        let n = lines.next().unwrap().parse::<usize>().unwrap();
        let s = lines.next().unwrap();
        let it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());

        let a = it.collect::<Vec<_>>();

        let (even, odd): (Vec<_>, Vec<_>) = a.iter().cloned().partition(|x| x % 2 == 0);

        let oans = (0..odd.len())
            .map(|i| {
                (i + 1..odd.len())
                    .map(|j| {
                        let mut x = odd[i];
                        let mut y = 2 * odd[j];
                        while y != 0 {
                            let t = x % y;
                            x = y;
                            y = t;
                        }
                        if x == 1 {
                            0u64
                        } else {
                            1
                        }
                    })
                    .sum::<u64>()
            })
            .sum::<u64>();

        let m = even.len() as u64;
        let eans = if m < 2 { 0 } else { (m * (m - 1)) / 2 } + m * (n as u64 - m);

        let ans = oans + eans;
        writeln!(&mut output, "{}", ans).unwrap();
    }
