        let c: char = it.next().unwrap().parse().unwrap();
        let s: String = it.next().unwrap().parse().unwrap();
        let mut moves = vec![];
        if s.chars().any(|x| x != c) {
            let mut ok = false;
            for i in (1..n).rev() {
                let _v: Vec<usize> = (i..n).step_by(i + 1).collect();

                if (i..n).step_by(i + 1).all(|j| s.as_bytes()[j] == c as u8) {
                    moves.push(i + 1);
                    ok = true;
                    break;
                }
            }
            if !ok {
                moves.push(n - 1);
                moves.push(n);
            }
        }
        let ans = format!("{}\n", moves.len());
        out.push_str(ans.as_str());
        for i in 0..moves.len() {
            if i + 1 == moves.len() {
                let ans = format!("{}\n", moves[i]);
                out.push_str(ans.as_str());
            } else {
                let ans = format!("{} ", moves[i]);
