                0usize,
                |acc, &x| if x == b'0' { acc.wrapping_add(1) } else { acc },
            );
            let ones = t.len().wrapping_sub(zeroes);
            let mut ans = 1usize.max(zeroes.wrapping_mul(ones));
            t.windows(2).fold(1usize, |a, c| {
                let b: usize = match c {
                    &[d, e] if d == e => a.wrapping_add(1),
                    _ => 1,
                };
                ans = ans.max(b.wrapping_mul(b));
                b
            });
            writeln!(buf, "{ans}").unwrap_or_default();
        });
