    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let C = buf_it.next().unwrap().chars().collect::<Vec<_>>();
    let N = C.len();

    let mut H = vec![0isize];
    for &c in &C {
        let h = H[H.len() - 1];
        match c {
            '/' => {
                H.push(h + 1);
            }
            '_' => {
                H.push(h);
            }
            '\\' => {
                H.push(h - 1);
            }
            _ => {}
        }
    }
    let mut L = H.clone();
    let mut R = H.clone();
    for i in 0..N {
        L[i + 1] = max(L[i], L[i + 1]);
        R[N - i - 1] = max(R[N - i - 1], R[N - i]);
    }
    let W = L
        .iter()
        .zip(R.iter())
        .map(|(a, b)| *min(a, b))
        .collect::<Vec<_>>();
    let mut ans = Vec::new();
    let mut tmp = 0;
    for i in 0..N + 1 {
        let h = H[i];
        let w = W[i];
        if w - h <= 0 && tmp > 0 {
            ans.push(tmp);
            tmp = 0;
        } else if w - h > 0 {
            tmp += w - h;
        }
    }
    println!("{}", ans.iter().sum::<isize>());
    if ans.is_empty() {
        println!("0");
    } else {
        println!(
            "{} {}",
            ans.len(),
            ans.iter()
                .map(|a| format!("{}", a))
                .collect::<Vec<_>>()
