        .split_whitespace()
        .map(|x| x.parse::<usize>().expect("convert to number"))
        .collect::<Vec<_>>();

    let n = arr[0];
    let m = arr[1];

    let matrix: Vec<_> = (0..n).map(|i| &arr[2 + i * m..2 + i * m + m]).collect();

    let combinations = 2usize.pow(m as u32);

    let (mut l, mut r) = (0, 1_000_000_001);

    let mut val_best = 0;
    let mut indices_chosen = None;

    while l + 1 < r {
        let mid = (l + r) / 2;

        let mut bitmasks = vec![false; combinations];
        let mut indices = vec![0; combinations];

        for (index, i) in matrix.iter().enumerate() {
            let mut mask = 0;
            for (ix, j) in i.iter().enumerate() {
                if j >= &mid {
                    mask |= 1 << ix;
                }
            }
            bitmasks[mask] = true;
            indices[mask] = index;
        }

        let mut found = false;
        'outer: for i in 0..combinations {
            for j in 0..combinations {
                let present = bitmasks[i] && bitmasks[j];

