      if (j + a[i] >= t) {
        break;
      }
      if (dp1[i - 1][j] + b[i] > dp1[i][j + a[i]]) {
        dp1[i][j + a[i]] = dp1[i - 1][j] + b[i];
      }
    }
  }
  for (long i = 0; i < t; i++) {
    dp2[n - 1][i] = 0;
  }
  if (a[n - 1] < t) {
    dp2[n - 1][a[n - 1]] = b[n - 1];
  }
