  for (long i = 0; i < n; i++) {
    for (long j = 1; j < t; j++) {
      if (dp1[i][j] < dp1[i][j - 1]) {
        dp1[i][j] = dp1[i][j - 1];
      }
      if (dp2[i][j] < dp2[i][j - 1]) {
        dp2[i][j] = dp2[i][j - 1];
      }
    }
  }
  long score;
  long max = 0;
  for (long last = 0; last < n; last++) {
    score = 0;
    if (last == 0) {
      for (long i = 0; i < t; i++) {
        if (dp2[1][i] > score) {
