void solution(unsigned long long arr[], size_t n) {
  if (n == 0)
    return;

  unsigned long long max = arr[0];

  for (size_t i = 1; i < n; i++) {
    if (arr[i] > max)
      max = arr[i];
  }

  size_t radix = 1;

  while (radix < n) {
    radix <<= 1;
  }

  unsigned long long *output = malloc(n * sizeof(unsigned long long));

  size_t *counter = malloc(radix * sizeof(size_t));

  if (!output || !counter) {
    free(output);
    free(counter);
    return;
  }

  unsigned long long place = 1;

  while (place <= max) {

    memset(counter, 0, radix * sizeof(size_t));

    for (size_t i = 0; i < n; i++) {
      size_t digit = (arr[i] / place) % radix;

      counter[digit]++;
    }

    for (size_t i = 1; i < radix; i++) {
      counter[i] += counter[i - 1];
    }

    for (size_t i = n; i > 0; i--) {
      unsigned long long value = arr[i - 1];

      size_t digit = (value / place) % radix;

      counter[digit]--;

      output[counter[digit]] = value;
    }

    memcpy(arr, output, n * sizeof(unsigned long long));

    place *= radix;
  }

  free(output);
  free(counter);
}

