fn solution() {
    let N: usize = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.trim().parse().unwrap()
    };
    let (a, b): (Vec<usize>, Vec<usize>) = {
        let (mut a, mut b) = (vec![], vec![]);
        for _ in 0..(N - 1) {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            a.push(iter.next().unwrap().parse().unwrap());
            b.push(iter.next().unwrap().parse().unwrap());
        }
        (a, b)
    };
    let M: usize = {
        let mut line: String = String::new();
        std::io::stdin().read_line(&mut line).unwrap();
        line.trim().parse().unwrap()
    };
    let (u, v): (Vec<usize>, Vec<usize>) = {
        let (mut u, mut v) = (vec![], vec![]);
        for _ in 0..M {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            u.push(iter.next().unwrap().parse().unwrap());
            v.push(iter.next().unwrap().parse().unwrap());
        }
        (u, v)
    };

    let G = {
        let mut G = vec![std::collections::HashMap::new(); N + 1];
        for i in 0..(N - 1) {
            G[a[i]].insert(b[i], i);
            G[b[i]].insert(a[i], i);
        }
        G
    };

    let mut dp = vec![std::collections::HashSet::new(); M];
    for i in 0..M {
        let mut prev = vec![(0, 0); N + 1];
        let mut q = std::collections::VecDeque::new();
        q.push_back(u[i]);
        while let Some(j) = q.pop_front() {
            for (&x, &e) in &G[j] {
                if prev[x].0 == 0 {
                    prev[x] = (j, e);
                    q.push_back(x);
                }
            }
        }
        let mut j = v[i];
        while j != u[i] {
            dp[i].insert(prev[j].1);
            j = prev[j].0;
        }
    }

    let mut res = 0i64;
    for i in 1..(1 << M) {
        let mut x = 0;
        let mut used = vec![false; N + 1];
        let mut s = 0;
        for j in 0..M {
            if (i >> j) & 1 == 1 {
                x += 1;
                for &y in &dp[j] {
                    if !used[y] {
                        s += 1;
                    }
                    used[y] = true;
                }
            }
        }
        let d = 1i64 << (N - 1 - s);

        if x % 2 == 1 {
            res += d;
        } else {
            res -= d;
        }
    }
    let ans = (1i64 << (N - 1)) - res;
    println!("{}", ans);
}

