            let count_with_pow_of_2 = counts_by_pow[pow_of_2] - already_used_pows;
            already_used_pows += count_with_pow_of_2;
            for _ in 0..count_with_pow_of_2 {
                ops_required += 1;
                if rem_pows_2 <= pow_of_2 {
                    rem_pows_2 = 0;
                    break;
                } else {
                    rem_pows_2 -= pow_of_2;
                }
            }
