            let b: usize = wr[i..j].iter().map(|&(w, r)| w + r).sum();
            let r: usize = wr[j..].iter().map(|&(_, r)| m - r).sum();

            let cost = w + b + r;
            if min > cost {
                min = cost;
            }
        }
    }
    cost += min;

    cost += lines
        .next()
        .unwrap()
        .bytes()
        .filter(|&ch| ch != b'R')
        .count();

