    let in_lock = std_in.lock();
    let input = BufReader::new(in_lock);

    let std_out = stdout();
    let out_lock = std_out.lock();
    let mut output = BufWriter::new(out_lock);

    let mut lines = input.lines().map(|r| r.unwrap());

    let s = lines.next().unwrap();
    let mut it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());

    let t = it.next().unwrap();

    for _ in 0..t {
        let s = lines.next().unwrap();
        let mut it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());
        let n = it.next().unwrap();

        let s = lines.next().unwrap();
        let it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());

        let mut stack = Vec::new();

        for (i, a) in it.enumerate().filter(|&(_, a)| a > 0) {
            let e = i + 1;
            let mut s = e.saturating_sub(a);

            loop {
                match stack.pop() {
                    None => {
                        stack.push((s, e));
                        break;
                    }
                    Some((s0, e0)) => {
                        if s <= e0 {
                            s = std::cmp::min(s0, s);
                        } else {
                            stack.push((s0, e0));
                            stack.push((s, e));
                            break;
                        }
                    }
                }
            }
        }

        let mut i = 0;

        for (s, e) in stack {
            for _ in i..s {
                write!(&mut output, "0 ").unwrap();
            }
            for _ in s..e {
                write!(&mut output, "1 ").unwrap();
            }
            i = e;
        }

        for _ in i..n {
            write!(&mut output, "0 ").unwrap();
        }

        writeln!(&mut output).unwrap();
    }
}

