fn solution() {
    let stdin = std::io::stdin();
    let stdin_lock = stdin.lock();
    let mut student_count = 0;
    let mut question_count = 0;
    let mut answers = Vec::<Vec<u8>>::new();
    let mut points = Vec::<u32>::new();
    for (line_count, line) in stdin_lock.lines().enumerate() {
        let line = line.unwrap();
        if line_count == 0 {
            let mut splitted = line.split_whitespace();
            student_count = usize::from_str(splitted.next().unwrap()).unwrap();
            question_count = usize::from_str(splitted.next().unwrap()).unwrap();
        } else if line_count > 0 && line_count <= student_count {
            answers.push(line.as_bytes().to_vec());
        } else {
            for s in line.split_whitespace() {
                points.push(u32::from_str(s).unwrap());
            }
            break;
        }
    }

    let mut out = 0;

    for i in 0..question_count {
        let mut v = [0u32; 5];
        for a in answers.iter() {
            match a[i] {
                b'A' => v[0] += 1,
                b'B' => v[1] += 1,
                b'C' => v[2] += 1,
                b'D' => v[3] += 1,
                b'E' => v[4] += 1,
                _ => {
                    unreachable!()
                }
            }
        }
        v.sort();
        out += v[4] * points[i];
    }
    println!("{}", out);
}

