fn solution() {
    let mut line = String::new();
    let stdin = io::stdin();
    let mut stdin = stdin.lock();
    stdin.read_line(&mut line).unwrap();
    let t: usize = line.trim().parse().unwrap();

    let stdout = io::stdout();
    let handle = stdout.lock();
    let mut buffer = BufWriter::with_capacity(65536, handle);
    for _t in 0..t {
        line.clear();
        stdin.read_line(&mut line).unwrap();
        let mut n_k = line.split_ascii_whitespace();
        let shelf_count: u32 = n_k.next().unwrap().parse().unwrap();
        let shelf_length: u32 = n_k.next().unwrap().parse().unwrap();

        if shelf_length == 1 || shelf_count & 1 == 0 {
            writeln!(&mut buffer, "YES").unwrap();

            let mut write_shelf = |start: &mut u32| {
                for _i in 0..shelf_length {
                    write!(&mut buffer, "{} ", start).unwrap();
                    *start += 2;
                }
                writeln!(&mut buffer).unwrap();
            };

            let mut last_even: u32 = 2;
            let mut last_odd: u32 = 1;
            for _i in 0..(shelf_count >> 1) {
                write_shelf(&mut last_odd);
                write_shelf(&mut last_even);
            }

            if shelf_count & 1 != 0 {
                write_shelf(&mut last_odd)
            }
        } else {
            writeln!(&mut buffer, "NO").unwrap();
        }
    }
    buffer.flush().unwrap();
}

