    let mut max_qual: i32 = -1;
    let mut max_qual_count: u32 = 0;

    for str_qual in buffer.split_ascii_whitespace() {
        let qual: i32 = str_qual.parse().unwrap();
        if qual > max_qual {
            max_qual = qual;
            max_qual_count = 1;
        } else if qual == max_qual {
            max_qual_count += 1;
        }
    }
    if max_qual_count >= 2 {
        println!("-1");
        return Ok(());
    }
    buffer.clear();
    input.read_line(&mut buffer)?;
    let m: usize = buffer.trim().parse().unwrap();
    let mut cheapest_boss: Vec<Option<u32>> = vec![None; n];
    for edge_line in input.lines().take(m) {
        let edge_spec: Vec<u32> = edge_line?
            .split_ascii_whitespace()
            .map(|x| x.parse().unwrap())
            .collect();
        let _a = edge_spec[0] - 1;
        let b = (edge_spec[1] - 1) as usize;
        let c = edge_spec[2];
        let curr_cheapest = cheapest_boss[b];
        if c < curr_cheapest.unwrap_or(c + 1) {
            cheapest_boss[b] = Some(c);
        }
    }
    let mut total: u64 = 0;
    let mut bossless: u32 = 0;
    for cheapest in cheapest_boss.iter() {
        match cheapest {
            None => {
                bossless += 1;
            }
            Some(cheapest) => {
                total += *cheapest as u64;
            }
        }
    }
    if bossless <= 1 {
        println!("{}", total);
