fn solution() {
    input! {
        n: usize,
        k: usize,
        d: [i64; n],
    }
    let n_act = min(n, k);
    let mut ans = 0;
    for a in 0..n_act + 1 {
        for b in 0..n_act + 1 - a {
            let rm = k - a - b;
            let mut acc_vec: Vec<i64> = d
                .iter()
                .take(a)
                .chain(d.iter().skip(n - b))
                .cloned()
                .collect();
            acc_vec.sort();
            let acc = acc_vec
                .iter()
                .enumerate()
                .filter(|&(i, x)| rm <= i || (rm > i && *x > 0))
                .map(|(_, x)| *x)
                .sum();
            ans = max(ans, acc);
        }
    }
    println!("{}", ans);
}

