            let mut cur = book;
            loop {
                loop_items.push(cur);
                cur = permutation[cur];
                if cur == book {
                    break;
                }
            }
            let length = loop_items.len();
            for item in 0..loop_items.len() {
                books[loop_items[item]] = length;
            }
            loop_items.clear();
        }
        loop_items.shrink_to_fit();
        for book in books {
            print!("{} ", book);
        }
