        let mut it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());

        let n = it.next().unwrap();

        let mut a = Vec::with_capacity(n);

        let s = lines.next().unwrap();
        let it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());
        a.extend(it.map(|x| x - 1));

        let mut z = vec![Vec::new(); n];

        for (i, x) in a.into_iter().enumerate() {
            z[x].push(i);
        }

        let mut e = vec![None; n];
        let mut ans = 0u64;

        for (i, l) in z.iter().enumerate() {
            if let Some(x) = l.iter().min_by_key(|&&x| z[x].len()).cloned() {
                e[x] = Some(i);
                ans += 1;
            }
