        let mut d = Vec::new();
        let mut b = Vec::new();

        while i < n && e[i].is_none() && z[i].is_empty() {
            i += 1;
        }

        for i in 0..n {
            match (e[i].is_some(), !z[i].is_empty()) {
                (false, false) => b.push(i),
                (false, true) => s.push(i),
                (true, false) => d.push(i),
                (true, true) => (),
            }
