    let std_out = stdout();
    let out_lock = std_out.lock();
    let mut output = BufWriter::new(out_lock);

    let mut lines = input.lines().map(|r| r.unwrap());

    let t = lines.next().unwrap().parse::<usize>().unwrap();

    for _ in 0..t {
        let s = lines.next().unwrap();
        let mut it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());
        let n = it.next().unwrap();
        let m = it.next().unwrap();

        let mut a = Vec::with_capacity(n);

        let s = lines.next().unwrap();
        a.extend(
            s.chars()
                .enumerate()
                .filter_map(|(i, c)| if c == '1' { Some(i) } else { None }),
        );

        if let Some(&i) = a.first() {
            let j = i.saturating_sub(m);

            for _ in 0..j {
                write!(&mut output, "0").unwrap();
            }
            for _ in j..i {
                write!(&mut output, "1").unwrap();
            }
        }

        for b in a.windows(2) {
            let i = b[0];
            let j = b[1];
            let k = j - i - 1;
            let q = k / 2;

            let x = std::cmp::min(m, q);

            write!(&mut output, "1").unwrap();

            for _ in 0..x {
                write!(&mut output, "1").unwrap();
            }
            for _ in 2 * x..k {
                write!(&mut output, "0").unwrap();
            }
            for _ in 0..x {
                write!(&mut output, "1").unwrap();
            }
        }

        if let Some(&i) = a.last() {
            let x = std::cmp::min(m + 1, n - i);

            for _ in 0..x {
