        cnt_h[p.0] += 1;
        cnt_w[p.1] += 1;
    }
    let max_h = *cnt_h.iter().max().unwrap();
    let max_w = *cnt_w.iter().max().unwrap();
    let overlap = cnt_h
        .iter()
        .fold(0, |a, &x| a + if x == max_h { 1 } else { 0 })
        * cnt_w
            .iter()
            .fold(0, |a, &x| a + if x == max_w { 1 } else { 0 });
    let cover = b.iter().fold(0, |a, &(x, y)| {
        a + if cnt_h[x] == max_h && cnt_w[y] == max_w {
            1
        } else {
            0
        }
    });
