    use std::cmp;

    use std::collections::HashMap;
    let mut ma = HashMap::new();
    let mut mb = HashMap::new();

    for i in 0..a.len() {
        let mut accm = 0;
        for j in i..a.len() {
            accm += a[j];
            if accm <= x {
                let num_squares = j - i + 1;
                if let std::collections::hash_map::Entry::Vacant(e) = ma.entry(num_squares) {
                    e.insert(accm);
                } else {
                    let v = *ma.get_mut(&num_squares).unwrap();
                    *(ma.get_mut(&num_squares).unwrap()) = cmp::min(v, accm);
                }
            }
        }
    }
    for i in 0..b.len() {
