    let s = lines.next().unwrap();
    let mut it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());
    let t = it.next().unwrap();

    'cases: for _case_index in 1..=t {
        let s = lines.next().unwrap();
        let mut it = s.split_whitespace().map(|s| s.parse::<usize>().unwrap());

        let n = it.next().unwrap();
        let m = it.next().unwrap();

        let mut grid = Vec::with_capacity(n * m);

        for _ in 0..n {
            for c in lines.next().unwrap().chars() {
                grid.push(match c {
                    'R' => 0,
                    'W' => 1,
                    _ => 2,
                })
            }
        }

        let mut r_even = None;

        for i in 0..n {
            for j in 0..m {
                let even = (i + j) % 2 == 0;
                let c = grid[i * m + j];
                if c == 2 {
                    continue;
                }

                if let Some(r) = r_even {
                    let o = if r && even || !r && !even { 0 } else { 1 };

                    if c != o {
                        writeln!(&mut output, "NO").unwrap();
                        continue 'cases;
                    }
