fn solution<T: Ord>(item: &T, arr: &[T]) -> Option<usize> {
    if arr.is_empty() {
        return None;
    }

    let is_asc = arr.len() > 1 && arr[0] < arr[arr.len() - 1];

    let mut left = 0;
    let mut right = arr.len() - 1;

    while left <= right {
        let first_mid = left + (right - left) / 3;
        let second_mid = right - (right - left) / 3;

        if first_mid == second_mid && first_mid == left {
            if &arr[left] == item {
                return Some(left);
            } else {
                left += 1;
                continue;
            }
        }

        let cmp_first_mid = item.cmp(&arr[first_mid]);
        let cmp_second_mid = item.cmp(&arr[second_mid]);

        match (is_asc, cmp_first_mid, cmp_second_mid) {
            (_, Ordering::Equal, _) => return Some(first_mid),
            (_, _, Ordering::Equal) => return Some(second_mid),

            (true, Ordering::Less, _) | (false, Ordering::Greater, _) => {
                if first_mid == 0 {
                    break;
                }
                right = first_mid - 1;
            }

            (true, _, Ordering::Greater) | (false, _, Ordering::Less) => {
                left = second_mid + 1;
            }

            (_, _, _) => {
                left = first_mid + 1;
                if second_mid == 0 {
                    break;
                }
                right = second_mid - 1;
            }
        }
    }

    None
}

