        .iter()
        .map(|s| s.iter().cloned().collect::<Vec<usize>>())
        .collect::<Vec<_>>();
    let mut done = vec![None; n];
    let mut ds = vec![];
    for i in 0..n {
        if done[i].is_some() {
            continue;
        }
        let mut ct: i64 = 1;
        let mut cf: i64 = 0;
        done[i] = Some(true);
        let mut st = vec![i];
        while let Some(v) = st.pop() {
