    let mut input_string = String::new();
    stdin.read_to_string(&mut input_string).unwrap();
    let mut input_iter = input_string.split_whitespace();




    let n: usize = read!();
    let m: usize = read!();
    let mut matrix = Vec::with_capacity(n);

    for _ in 0..n {
        let row_string: String = read!();
        let row = row_string.chars().collect::<Vec<char>>();
        matrix.push(row);
    }

    if n == 1 || m == 1 {
        println!("0");
        return;
    }

    if n > 3 && m > 3 {
        println!("-1");
        return;
    }

    if m > n {
        let matrix_clone = matrix;
        matrix = vec![vec!['_'; n]; m];
        for i in 0..n {
            for j in 0..m {
                matrix[j][i] = matrix_clone[i][j];
            }
        }
    }

    let decimal_vector: Vec<u32> = matrix
        .iter()
        .map(|row| row.iter().collect::<String>())
        .map(|row_str| u32::from_str_radix(&row_str, 2).unwrap())
        .collect();

    let mut possible_adjacent_values = vec![vec![(0, 0); 8]; 4];

    possible_adjacent_values[2][0b_00] = (0b_01, 0b_10);
    possible_adjacent_values[2][0b_01] = (0b_00, 0b_11);
    possible_adjacent_values[2][0b_10] = (0b_00, 0b_11);
    possible_adjacent_values[2][0b_11] = (0b_01, 0b_10);

    possible_adjacent_values[3][0b_000] = (0b_010, 0b_101);
    possible_adjacent_values[3][0b_001] = (0b_011, 0b_100);
    possible_adjacent_values[3][0b_010] = (0b_000, 0b_111);
    possible_adjacent_values[3][0b_011] = (0b_001, 0b_110);
    possible_adjacent_values[3][0b_100] = (0b_001, 0b_110);
    possible_adjacent_values[3][0b_101] = (0b_000, 0b_111);
    possible_adjacent_values[3][0b_110] = (0b_011, 0b_100);
    possible_adjacent_values[3][0b_111] = (0b_010, 0b_101);

    let width = min(n, m);
    let mut mask_upperbound = 8;
    if width == 2 {
        mask_upperbound = 4;
    }

    let mut min_cost = vec![vec![0; mask_upperbound]; decimal_vector.len()];

    for mask in 0..mask_upperbound {
        min_cost[0][mask] = ((mask as u32) ^ decimal_vector[0]).count_ones();
    }

    for i in 1..decimal_vector.len() {
        for mask in 0..mask_upperbound {
            let change_to_mask_cost = ((mask as u32) ^ decimal_vector[i]).count_ones();
            let (a, b) = possible_adjacent_values[width][mask];
            min_cost[i][mask] = change_to_mask_cost + min(min_cost[i - 1][a], min_cost[i - 1][b]);
        }
    }

    println!(
        "{}",
        min_cost[decimal_vector.len() - 1].iter().min().unwrap()
    );
}

