fn solution() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();
    let mut buf_it = buf.split_whitespace();

    let N = buf_it.next().unwrap().parse::<usize>().unwrap();
    let P = (0..N * N)
        .map(|_| buf_it.next().unwrap().parse::<usize>().unwrap() - 1)
        .collect::<Vec<_>>();

    let mut ans = 0;
    let mut cost = (0..N)
        .map(|_| (0..N).map(|_| 0).collect::<Vec<_>>())
        .collect::<Vec<_>>();
    let mut seated = (0..N)
        .map(|_| (0..N).map(|_| 1).collect::<Vec<_>>())
        .collect::<Vec<_>>();
    for i in 0..N {
        for j in 0..N {
            let mut tmp = min(i, N - 1 - i);
            tmp = min(tmp, j);
            tmp = min(tmp, N - 1 - j);
            cost[i][j] = tmp;
        }
    }

    for p in P {
        let i = p % N;
        let j = p / N;
        ans += cost[i][j];
        seated[i][j] = 0;
        let mut q = vec![(i, j)];
        while !q.is_empty() {
            let mut qq = Vec::new();
            while let Some((i, j)) = q.pop() {
                let c = cost[i][j] + seated[i][j];
                let i = i as isize;
                let j = j as isize;
                for (di, dj) in [(1, 0), (-1, 0), (0, 1), (0, -1)] {
                    let i = i + di;
                    let j = j + dj;
                    if i < 0 || i >= (N as isize) || j < 0 || j >= (N as isize) {
                        continue;
                    }
                    let i = i as usize;
                    let j = j as usize;
                    if cost[i][j] <= c {
                        continue;
                    }
                    cost[i][j] = c;
                    qq.push((i, j));
                }
            }
            q = qq;
        }
    }

    println!("{}", ans);
}

