    buckets[i] = NULL;
  }

  for (i = 0; i < NARRAY; ++i) {
    struct Node *current;
    int pos = arr[i] / INTERVAL;

    current = (struct Node *)malloc(sizeof(struct Node));
    current->data = arr[i];

    current->next = buckets[pos];
    buckets[pos] = current;
  }

  for (i = 0; i < NBUCKET; i++) {
    struct Node *p;

    printf("Bucket[\"%d\"] : ", i);

    p = buckets[i];
    while (p) {
      printf("%d ", p->data);
      p = p->next;
    }

    printf("\n");
  }

  for (i = 0; i < NBUCKET; ++i) {
    struct Node *list;
    struct Node *k;

    list = buckets[i];

    if (list == NULL || list->next == NULL) {
      buckets[i] = list;
      continue;
    }

    k = list->next;
    list->next = NULL;

    while (k != NULL) {
      struct Node *ptr;

      if (list->data > k->data) {
        struct Node *tmp;

        tmp = k;
        k = k->next;

        tmp->next = list;
        list = tmp;

        continue;
      }

      for (ptr = list; ptr->next != NULL; ptr = ptr->next) {
        if (ptr->next->data > k->data)
          break;
      }

      if (ptr->next != NULL) {
        struct Node *tmp;

        tmp = k;
        k = k->next;

        tmp->next = ptr->next;
        ptr->next = tmp;

        continue;
      } else {

        ptr->next = k;
        k = k->next;

        ptr->next->next = NULL;

        continue;
      }
    }

    buckets[i] = list;
  }

  printf("--------------\n");
  printf("Buckets after sorted\n");

  for (i = 0; i < NBUCKET; i++) {
