    let mut lines = String::new();
    let _ = stdin.read_to_string(&mut lines);
    let vec = lines.lines().collect::<Vec<&str>>();
    let firstline = vec[0].split(' ').collect::<Vec<&str>>();
    let n: usize = firstline[0].trim().parse().unwrap();
    let m: usize = firstline[1].trim().parse().unwrap();
    let mut hens: Vec<(usize, usize)> = Vec::new();
    for i in 0..m {
        let thisline = vec[i + 1].split(' ').collect::<Vec<&str>>();
        let a: usize = thisline[0].trim().parse().unwrap();
        let b: usize = thisline[1].trim().parse().unwrap();
        hens.push((a - 1, b - 1));
    }
    let hens = hens;
    let mut dp: Vec<usize> = vec![0; n * (1 << n)];
    dp[n] = 1;
    for i in 2..(1 << n) {
        for j in 0..n {
            if (1 << j) & i == 0 {
                continue;
            }
            for &(a, b) in &hens {
                let tail = if a == j {
                    b
                } else if b == j {
                    a
                } else {
                    n
                };
                if tail == n {
                    continue;
                }
                dp[i * n + j] += dp[(i ^ (1 << j)) * n + tail];
            }
        }
    }
    let mut fin = 0;
    for i in 0..n {
        fin += dp[((1 << n) - 1) * n + i];
    }
