    node[i][n_edge[i] - 1] = j;
    node[j] = (int *)realloc(node[j], sizeof(int) * n_edge[j]);
    node[j][n_edge[j] - 1] = i;
  }

  int start = 1;
  int end = start;
  int vacant = 2;
  int queue[N + 1];
  int state[N + 1];
  for (int i = 1; i <= N; i++) {
    state[i] = -1;
