    for (int current = start; current <= end; current++) {
      int base = queue[current];
      for (int i = 0; i < n_edge[base]; i++) {
        int neighbor = node[base][i];
        if (state[neighbor] < 0) {
          queue[vacant] = neighbor;
          state[neighbor] = base;
