fn solution() {
    let mut input = String::new();
    use std::io;
    use std::io::prelude::*;
    io::stdin().read_to_string(&mut input).unwrap();

    let mut it = input.split_whitespace();

    let n: usize = it.next().unwrap().parse().unwrap();
    let k: usize = it.next().unwrap().parse().unwrap();

    let s = it.next().unwrap().as_bytes();

    let mut set = [false; 26];

    for &b in s.iter() {
        set[(b - b'a') as usize] = true;
    }

    let first = set.iter().position(|&x| x).unwrap() as u8;
    let last = set.iter().rposition(|&x| x).unwrap() as u8;

    use std::cmp::Ordering;

    match n.cmp(&k) {
        Ordering::Less => {
            let mut ans = s.to_vec();
            for _ in n..k {
                ans.push(first + b'a');
            }
            let ans = std::str::from_utf8(&ans).unwrap();

            println!("{}", ans);
        }
        Ordering::Equal | Ordering::Greater => {
            let pos = s[..k].iter().rposition(|&b| b != last + b'a').unwrap();
            let mut ans = s[..k].to_vec();
            let b = ans[pos] - b'a';
            let next = set[b as usize..].iter().skip(1).position(|&x| x).unwrap() as u8 + b + 1;
            ans[pos] = next + b'a';
            for b in ans[pos..].iter_mut().skip(1) {
                *b = first + b'a';
            }
            let ans = std::str::from_utf8(&ans).unwrap();
            println!("{}", ans);
        }
    }
}

