fn solution() {
    let mut input_str = String::new();
    std::io::stdin().read_to_string(&mut input_str).unwrap();

    let input_parts = input_str.split_whitespace().collect::<Vec<_>>();
    let mut input_parts_it = input_parts.iter().cloned();
    let mut next = || input_parts_it.next().unwrap();

    let h: usize = next().parse().unwrap();
    let w: usize = next().parse().unwrap();
    let a_map: Vec<i32> = (0..(w * h)).map(|_| next().parse().unwrap()).collect();
    let b_map: Vec<i32> = (0..(w * h)).map(|_| next().parse().unwrap()).collect();

    let idx = |x: usize, y: usize| x + y * w;

    let mut costs: Vec<Vec<i32>> = vec![Vec::new(); a_map.len()];

    let mut buf = Vec::new();

    for y in 0..h {
        for x in 0..w {
            buf.clear();

            if x == 0 && y == 0 {
                buf.push(0);
            }
            if x > 0 {
                buf.extend(costs[idx(x - 1, y)].iter().cloned());
            }
            if y > 0 {
                buf.extend(costs[idx(x, y - 1)].iter().cloned());
            }

            let (a, b) = (a_map[idx(x, y)], b_map[idx(x, y)]);

            let out_cost = &mut costs[idx(x, y)];
            out_cost.reserve(buf.len() * 2);
            out_cost.extend(buf.iter().map(|&x| x + (a - b)));
            out_cost.extend(buf.iter().map(|&x| x + (b - a)));
            out_cost.sort();
            out_cost.dedup();
        }
    }

    let goal = costs.last().unwrap();

    let best = goal.iter().map(|&cost| cost.abs()).min().unwrap();

    println!("{}", best);
}

