    stdin().read_to_string(&mut s).ok();
    let mut itr = s.split_whitespace();
    let t: usize = itr.next().unwrap().parse().unwrap();
    let mut out = Vec::new();
    for _ in 0..t {
        let h: usize = itr.next().unwrap().parse().unwrap();
        let w: usize = itr.next().unwrap().parse().unwrap();
        let g: Vec<Vec<usize>> = (0..h)
            .map(|_| {
                (0..w)
                    .map(|_| itr.next().unwrap().parse().unwrap())
                    .collect()
            })
            .collect();
        let mut sum = vec![(0, 0); h + w];
        for i in 0..h {
            for j in 0..w {
                if g[i][j] == 0 {
                    sum[i + j].0 += 1;
                } else {
                    sum[i + j].1 += 1;
                }
            }
        }
        let last = h + w - 2;
        let mut ans = 0;

        for i in 0..last / 2 {
            let zero = sum[i].0 + sum[last - i].0;
            let one = sum[i].1 + sum[last - i].1;
            ans += min(zero, one);
        }
        if (h + w) % 2 == 1 {
            let i = last / 2;
            let j = last / 2 + 1;
            let zero = sum[i].0 + sum[j].0;
            let one = sum[i].1 + sum[j].1;
            ans += min(zero, one);
        }
        writeln!(out, "{}", ans).ok();
    }
    stdout().write_all(&out).unwrap();
}

