fn solution() {
    let std_in = stdin();
    let in_lock = std_in.lock();
    let input = BufReader::new(in_lock);

    let std_out = stdout();
    let out_lock = std_out.lock();
    let mut output = BufWriter::new(out_lock);

    let mut lines = input.lines().map(|r| r.unwrap());
    let t = lines.next().unwrap().parse::<usize>().unwrap();

    'cases: for _ in 0..t {
        let n = lines.next().unwrap().parse::<usize>().unwrap();

        let mut a = lines.next().unwrap().into_bytes();

        let (first_span, s) = match a.iter().position(|&b| b != b'?') {
            Some(i) => a.split_at_mut(i),
            None => {
                let mut i = 0;
                while i < n {
                    output.write(b"B").unwrap();
                    i += 1;
                    if i == n {
                        break;
                    }
                    output.write(b"R").unwrap();
                    i += 1;
                }
                writeln!(&mut output).unwrap();
                continue 'cases;
            }
        };

        let j = s
            .iter()
            .enumerate()
            .rev()
            .find_map(|(j, &b)| if b != b'?' { Some(j) } else { None })
            .unwrap();
        let (s, last_span) = s.split_at_mut(j + 1);

        let mut x = *s.first().unwrap() == b'B';
        for b in first_span.iter_mut().rev() {
            x = !x;
            *b = if x { b'B' } else { b'R' }
        }

        let mut x = *s.last().unwrap() == b'B';
        for b in last_span.iter_mut() {
            x = !x;
            *b = if x { b'B' } else { b'R' }
        }

        let mut x = *s.first().unwrap() == b'B';
        for b in s.iter_mut().skip(1) {
            match *b {
                b'R' => x = false,
                b'B' => x = true,
                _ => {
                    x = !x;
                    *b = if x { b'B' } else { b'R' }
                }
            }
        }

        output.write_all(a.as_slice()).unwrap();
        writeln!(&mut output).unwrap();
    }
}

