  long long int m;
  scanf("%lli %lli", &n, &m);
  int i;
  int rows[n + 1];
  int columns[n + 1];
  int rws = 0;
  int cols = 0;
  long long int frees[m];
  long long int freeCounter = 0;
  for (i = 1; i <= n; i++) {
    rows[i] = columns[i] = 0;
  }
  long long int free = n * n;
  for (i = 0; i < m; i++) {
    int x;
    int y;
    scanf("%d %d", &x, &y);
    if (rows[x] + columns[y] == 2) {
      frees[freeCounter] = free;
      freeCounter++;
      continue;
    }
    if (rows[x] + columns[y] == 0) {
      free -= 2 * n - 1 - (rws + cols);
      rws++;
      cols++;
      rows[x] = 1;
      columns[y] = 1;
    } else if (columns[y] == 1) {
      free -= n - cols;
      rows[x] = 1;
      rws++;
    } else if (rows[x] == 1) {
      free -= n - rws;
      columns[y] = 1;
      cols++;
    }
    frees[freeCounter] = free;
    freeCounter++;
  }
  for (i = 0; i < freeCounter; i++) {
    printf("%lli ", frees[i]);
  }
  printf("\n");
  return 0;
}

