  for (j = 0, i = 0; i < M; j++) {
    if (bucket_1[j] != 0) {
      ary[i] = j - 100000;
      i++;
    }
  }

  for (i = 0; i < M - 1; i++) {
    margin[i] = ary[i + 1] - ary[i];
  }

  for (i = 0; i < M - 1; i++) {
    bucket_2[margin[i] - 1] += 1;
  }
  for (i = 0, j = 0; i < M - 1; j++) {
    if (bucket_2[j] != 0) {
      for (k = 0; k < bucket_2[j]; k++) {
        margin[i] = j + 1;
        i++;
      }
    }
  }

  for (i = M - 2; M - N - 1 < i; i--) {
    notpass += margin[i];
  }

  printf("%d\n", ary[M - 1] - ary[0] - notpass);

