fn solution() {
    let mut s = String::new();
    use std::io::Read;
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut s = s.split_whitespace();
    let h: usize = s.next().unwrap().parse().unwrap();
    let w: usize = s.next().unwrap().parse().unwrap();
    let k: i32 = s.next().unwrap().parse().unwrap();
    let sy = s.next().unwrap().parse::<usize>().unwrap() - 1;
    let sx = s.next().unwrap().parse::<usize>().unwrap() - 1;
    let gy = s.next().unwrap().parse::<usize>().unwrap() - 1;
    let gx = s.next().unwrap().parse::<usize>().unwrap() - 1;
    let field: Vec<Vec<_>> = s.take(h).map(|s| s.chars().collect()).collect();

    let mut dist = vec![vec![[std::i32::MAX; 4]; w]; h];
    use std::cmp::Reverse;
    let mut q = std::collections::BinaryHeap::new();
    q.push((Reverse(0), sy, sx, 4));
    while let Some((Reverse(cost), y, x, d)) = q.pop() {
        if d != 4 && cost > dist[y][x][d] {
            continue;
        }
        for &(ny, nx, nd) in [
            (y, x + 1, 0),
            (y.wrapping_sub(1), x, 1),
            (y, x.wrapping_sub(1), 2),
            (y + 1, x, 3),
        ]
        .iter()
        .filter(|&&(ny, nx, _)| (y, x) != (ny, nx) && ny < h && nx < w && field[ny][nx] == '.')
        {
            if d == nd {
                if cost + 1 < dist[ny][nx][nd] {
                    dist[ny][nx][d] = cost + 1;
                    q.push((Reverse(cost + 1), ny, nx, d));
                }
            } else {
                let nc = 1 + (cost + k - 1) / k * k;
                if nc < dist[ny][nx][nd] {
                    dist[ny][nx][nd] = nc;
                    q.push((Reverse(nc), ny, nx, nd));
                }
            }
        }
    }
    let ans = dist[gy][gx]
        .iter()
        .map(|&d| {
            if d == std::i32::MAX {
                std::i32::MAX
            } else {
                (d + k - 1) / k
            }
        })
        .min()
        .unwrap();
    if ans == std::i32::MAX {
        println!("-1");
    } else {
        println!("{}", ans);
    }
}

