int64_t solution(const int64_t *arr, const uint16_t length,
                           const int64_t n) {
  if (length == 0) {
    return -1;
  }

  uint32_t upper_bound = 1;
  while (upper_bound < length && arr[upper_bound] < n) {
    upper_bound = upper_bound * 2;
  }

  uint16_t lower_bound = upper_bound / 2;
  if (upper_bound >= length) {
    upper_bound = length - 1;
  }

  while (lower_bound <= upper_bound) {
    uint16_t middle_index = lower_bound + (upper_bound - lower_bound) / 2;

    if (arr[middle_index] == n) {
      return middle_index;
    }

    if (arr[middle_index] > n) {

      if (middle_index == 0) {
        break;
      }
      upper_bound = middle_index - 1;
    } else {

      lower_bound = middle_index + 1;
    }
  }

  return -1;
}

