fn solution() {
    let mut input_str = String::new();
    std::io::stdin().read_to_string(&mut input_str).unwrap();

    let input_parts = input_str.split_whitespace().collect::<Vec<_>>();
    let mut input_parts_it = input_parts.iter().cloned();

    let n: usize = input_parts_it.next().unwrap().parse().unwrap();
    let k: u64 = input_parts_it.next().unwrap().parse().unwrap();

    let a: Vec<u32> = (0..n)
        .map(|_| input_parts_it.next().unwrap().parse().unwrap())
        .collect();

    const NONE: usize = 0xffffffff;
    let mut group_end: Vec<usize> = vec![NONE; a.len()];

    let mut next_a_same_value_for_a: Vec<usize> = vec![NONE; a.len()];
    let mut last_a_for_aval: Vec<usize> = vec![NONE; 200001];

    for (i, &aval) in a.iter().enumerate().rev() {
        next_a_same_value_for_a[i] = last_a_for_aval[aval as usize];
        last_a_for_aval[aval as usize] = i;
    }

    for (i, &aval) in a.iter().enumerate() {
        let mut k = next_a_same_value_for_a[i];
        if k == NONE {
            k = last_a_for_aval[aval as usize];
            debug_assert!(k != NONE);
            k += a.len();
        }
        k += 1;

        group_end[i] = k;
    }

    let mut cycle_len = 0;
    {
        let mut i = 0;
        loop {
            let hop = group_end[i] - i;
            cycle_len += hop as u64;
            i = group_end[i];
            while i >= a.len() {
                i -= a.len();
            }
            if i == 0 {
                break;
            }
        }
    }

    let mut step = n as u64 * k;
    step %= cycle_len;

    let mut state: Vec<u32> = Vec::with_capacity(a.len());
    let mut index: Vec<usize> = vec![NONE; 200001];

    {
        let mut i = 0;
        let mut remaining_steps = step;

        while remaining_steps >= (group_end[i] - i) as u64 {
            remaining_steps -= (group_end[i] - i) as u64;
            i = group_end[i];
            while i >= a.len() {
                i -= a.len();
            }
        }

        while remaining_steps > 0 {
            let aval = a[i];

            if index[aval as usize] == NONE {
                index[aval as usize] = state.len();
                state.push(aval);
            } else {
                while state.len() > index[aval as usize] {
                    let k = state.pop().unwrap();
                    index[k as usize] = NONE;
                }
            }

            i += 1;
            while i >= a.len() {
                i -= a.len();
            }
            remaining_steps -= 1;
        }
    }

    if state.is_empty() {
        println!();
    } else {
        print!("{}", state[0]);
        for &x in state[1..].iter() {
            print!(" {}", x);
        }
    }
}

