fn solution<T: Ord>(arr: &mut [T]) {
    if arr.is_empty() {
        return;
    }

    fn sort<T: Ord>(arr: &mut [T], start: usize, end: usize) {
        if arr[start] > arr[end] {
            arr.swap(start, end);
        }

        if start + 1 >= end {
            return;
        }

        let k = (end - start + 1) / 3;

        sort(arr, start, end - k);
        sort(arr, start + k, end);
        sort(arr, start, end - k);
    }

    sort(arr, 0, arr.len() - 1);
}

