int solution(const int *arr, int x, size_t n) {
  if (n == 0)
    return -1;

  size_t step = (size_t)floor(sqrt((double)n));
  size_t prev = 0;
  size_t current_limit;

  while (1) {
    current_limit = (step < n) ? step : n;

    if (arr[current_limit - 1] >= x) {
      break;
    }

    prev = step;
    step += (size_t)floor(sqrt((double)n));

    if (prev >= n) {
      return -1;
    }
  }

  current_limit = (step < n) ? step : n;
  while (arr[prev] < x) {
    prev++;
    if (prev == current_limit) {
      return -1;
    }
  }

  if (arr[prev] == x) {
    return (int)prev;
  }

  return -1;
}

